import { BaseClassTemplate } from '@_core/__base';
import { Component, OnInit} from '@angular/core';

import { ViewEncapsulation, ChangeDetectionStrategy } from '@angular/core';
import { MyForm } from './form';
import { TMSubmit } from '@_core/_form';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  host: { style: "width: 100% !important" },
  selector: 'aam-admin-add',
  templateUrl: './admin-add.html',
})
export class AdminAdd extends BaseClassTemplate implements OnInit {


  ngOnInit(): void {
    this.InitForm();
  }
  InitForm(){
    MyForm(this);
    this._template.tmSubmit = new TMSubmit(this, {
      srvc: URL_SRVC.Userz,
      cntrl: URL_CONTRL.Userz.UserzAdmin,
    })
    .init();


    this._template.tmSubmit.httpResSingle.subscribe({
      next: (d) => this._fs._form.patchValue(d)
    })
  }
  onEdit() {

  }

}
