import { BaseClassSrvc } from '@_core/__base';
import { FormBaseUserz } from '@_feature/userz/z-form-userz/userz.form';

export function MyForm(that: BaseClassSrvc, d: any = {}) {
  that._fs._form = that._fb.group({
    ...FormBaseUserz(that, d),
    userzTeacherId: [d?.userzTeacherId || '', that._vs._val('Teacher')],
    userzParentId: [d?.userzParentId || '', that._vs._val('Parent')],
  });
}
