import { Routes } from "@angular/router";
import { Admin } from "./admin/admin";
import { AdminAdd } from "./admin/admin-add/admin-add";
import { Student } from "./student/student";
import { StudentAdd } from "./student/student-add/student-add";
import { Teacher } from "./teacher/teacher";
import { TeacherAdd } from "./teacher/teacher-add/teacher-add";
import { Parent } from "./parent/parents";
import { ParentAdd } from "./parent/parent-add/parents-add";
import { RoutezFeatureModule } from "@_core/_route";

export const Routez: Routes = new RoutezFeatureModule (
  ['User'],
  'feature/user'
)
.feature(Admin, AdminAdd, 'admin', 'Admin')
.feature(Teacher, TeacherAdd, 'teacher', 'Teacher')
.feature(Parent, ParentAdd, 'parent', 'Parent')
.feature(Student, StudentAdd, 'student', 'Student Profile')
.build();
