import { BaseClassTemplate } from '@_core/__base';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';
import { TM_List } from '@_core/_pagination';
import { Component, OnInit} from '@angular/core';

import { ViewEncapsulation, ChangeDetectionStrategy } from '@angular/core';
import { TeacherFilter } from './teacher-filter/teacher-filter';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-teacher',
  templateUrl: './teacher.html',

})
export class Teacher extends BaseClassTemplate implements OnInit {
  ngOnInit() {
    this.initTables();
  }
  initTables() {
    this._template.lb = new TM_List(this,
      {
        srvc: URL_SRVC.Userz,
        cntrl: URL_CONTRL.Userz.UserzTeacher,
      },
      [
        { key: 'gender', name: 'Gender'},
        { key: 'email', name: 'Email'},
        { key: 'phone', name: 'Phone'},
      ],
    ).init();

    // this._template.lb.filterComponent = StudentFilter;
    this._template.lb.filterAdvance = this._fb.group({
      gender: [null],
      email: [null],
      phone: [null],
    });
    // this._template.lb.filterShow();
    this._sideNav.showRight(TeacherFilter);
  }
}
