import { BaseClassTemplate } from '@_core/__base';
import { Component, OnInit} from '@angular/core';

import { ViewEncapsulation, ChangeDetectionStrategy } from '@angular/core';
import { MyForm } from '@_feature/userz/admin/admin-add/form';
import { TMSubmit } from '@_core/_form';
import { URL_CONTRL, URL_SRVC } from '@_core/_client';

@Component({
  standalone: false,
  encapsulation: ViewEncapsulation.None,
  changeDetection: ChangeDetectionStrategy.OnPush,
  selector: 'aam-teacher-add',
  templateUrl: './teacher-add.html',
})
export class TeacherAdd extends BaseClassTemplate implements OnInit {


  ngOnInit(): void {
    this.InitForm();
  }
  InitForm(){
    MyForm(this);
    this._template.tmSubmit = new TMSubmit(this, {
      srvc: URL_SRVC.Userz,
      cntrl: URL_CONTRL.Userz.UserzTeacher,
    })
    .init();


    this._template.tmSubmit.httpResSingle.subscribe({
      next: (d) => this._fs._form.patchValue(d)
    })
  }
  onEdit() {

  }

}
